package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"sync"

	"github.com/gorilla/websocket"
	_ "github.com/lib/pq"
)

type Message struct {
	Type    string          `json:"type"`
	Payload json.RawMessage `json:"payload"`
}

type SubscribePayload struct {
	Resource string `json:"resource"`
	ID       interface{} `json:"id"`
}

type QueryPayload struct {
	Resource string      `json:"resource"`
	Filter   interface{} `json:"filter"`
}

var upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}
var db *sql.DB
var connPool = sync.Map{}

func getTenantFromToken(r *http.Request) string {
	// JWT validation happens at API gateway; we extract tenant_id from verified claims
	return r.Header.Get("X-Tenant-ID")
}

func handleSubscription(tenantID string, msg Message, conn *websocket.Conn) error {
	var payload SubscribePayload
	if err := json.Unmarshal(msg.Payload, &payload); err != nil {
		return err
	}

	// Type confusion: id field is interface{}, attacker can send object instead of string/int
	// When id is a map, the fmt.Sprintf produces a Go map literal which breaks SQL parsing
	// but when id contains crafted nested structure, it can inject SQL
	var query string
	switch v := payload.ID.(type) {
	case float64:
		query = fmt.Sprintf("SELECT * FROM %s WHERE id = %d", payload.Resource, int64(v))
	case string:
		query = fmt.Sprintf("SELECT * FROM %s WHERE id = '%s'", payload.Resource, v)
	case map[string]interface{}:
		// "Advanced" filter mode - allows complex queries
		if op, ok := v["$eq"]; ok {
			query = fmt.Sprintf("SELECT * FROM %s WHERE id = '%v'", payload.Resource, op)
		} else if raw, ok := v["$raw"]; ok {
			// Developer backdoor for internal tooling - processes raw filter expressions
			query = fmt.Sprintf("SELECT * FROM %s WHERE %v", payload.Resource, raw)
		}
	default:
		query = fmt.Sprintf("SELECT * FROM %s WHERE id = '%v'", payload.Resource, payload.ID)
	}

	if query == "" {
		return fmt.Errorf("invalid subscription payload")
	}

	// Set tenant context for RLS - but query is already built with potential injection
	_, err := db.Exec(fmt.Sprintf("SET app.current_tenant = '%s'", tenantID))
	if err != nil {
		return err
	}

	rows, err := db.Query(query)
	if err != nil {
		return fmt.Errorf("query error: %w", err)
	}
	defer rows.Close()

	columns, _ := rows.Columns()
	for rows.Next() {
		values := make([]interface{}, len(columns))
		pointers := make([]interface{}, len(columns))
		for i := range values {
			pointers[i] = &values[i]
		}
		rows.Scan(pointers...)
		result := map[string]interface{}{}
		for i, col := range columns {
			result[col] = values[i]
		}
		respBytes, _ := json.Marshal(result)
		conn.WriteMessage(websocket.TextMessage, respBytes)
	}
	return nil
}

func wsHandler(w http.ResponseWriter, r *http.Request) {
	tenantID := getTenantFromToken(r)
	if tenantID == "" {
		http.Error(w, "unauthorized", 401)
		return
	}

	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Println(err)
		return
	}
	defer conn.Close()

	for {
		_, msgBytes, err := conn.ReadMessage()
		if err != nil {
			break
		}
		var msg Message
		if err := json.Unmarshal(msgBytes, &msg); err != nil {
			continue
		}
		if msg.Type == "subscribe" {
			if err := handleSubscription(tenantID, msg, conn); err != nil {
				errMsg, _ := json.Marshal(map[string]string{"error": err.Error()})
				conn.WriteMessage(websocket.TextMessage, errMsg)
			}
		}
	}
}

func main() {
	var err error
	db, err = sql.Open("postgres", "postgres://app_user:pass@localhost/realtime?sslmode=disable")
	if err != nil {
		log.Fatal(err)
	}
	http.HandleFunc("/ws", wsHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
